# Expected values are SymPy's outputs for the same calls (categories).

A <- Object("A"); B <- Object("B"); C <- Object("C"); D <- Object("D")
f <- NamedMorphism(A, B, "f"); g <- NamedMorphism(B, C, "g"); h <- NamedMorphism(C, D, "h")
fmt <- function(r) {
  if (is.logical(r)) return(if (isTRUE(r)) "True" else "False")
  if (is.list(r) && !is_sym(r)) return(paste0("(", paste(vapply(r, fmt, ""), collapse = ", "), ")"))
  sstr(r)
}

test_that("categories match SymPy", {
  expect_equal(fmt(morphism_domain(f)), "Object(\"A\")")
  expect_equal(fmt(codomain(f)), "Object(\"B\")")
  expect_equal(fmt(codomain(IdentityMorphism(A))), "Object(\"A\")")
  expect_equal(fmt(CompositeMorphism(f)), "NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\")")
  expect_equal(fmt(g * f), "CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\")))")
  expect_equal(fmt(morphism_domain(g * f)), "Object(\"A\")")
  expect_equal(fmt(codomain(g * f)), "Object(\"C\")")
  expect_equal(fmt(do.call(Tuple, components(g * f))), "(NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"))")
  expect_equal(fmt(CompositeMorphism(f, g)), "CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\")))")
  expect_equal(fmt(CompositeMorphism(g * f)), "CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\")))")
  expect_equal(fmt(h * g * f), "CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"), NamedMorphism(Object(\"C\"), Object(\"D\"), \"h\")))")
  expect_equal(fmt(h * (g * f)), "CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"), NamedMorphism(Object(\"C\"), Object(\"D\"), \"h\")))")
  expect_equal(fmt(CompositeMorphism(f, g, h)), "CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"), NamedMorphism(Object(\"C\"), Object(\"D\"), \"h\")))")
  expect_equal(fmt(flatten_morphism(h * g * f, "u")), "NamedMorphism(Object(\"A\"), Object(\"D\"), \"u\")")
  expect_equal(fmt(f * IdentityMorphism(A)), "NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\")")
  expect_equal(fmt(IdentityMorphism(B) * f), "NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\")")
  expect_equal(fmt(IdentityMorphism(A) * IdentityMorphism(A)), "IdentityMorphism(Object(\"A\"))")
  expect_equal(fmt(CompositeMorphism(IdentityMorphism(A))), "IdentityMorphism(Object(\"A\"))")
  expect_equal(fmt(Diagram()), "Diagram({}, {}, EmptySet)")
  expect_equal(fmt(Diagram(list(f))), "Diagram({IdentityMorphism(Object(\"A\")): EmptySet, IdentityMorphism(Object(\"B\")): EmptySet, NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"): EmptySet}, {}, {Object(\"A\"), Object(\"B\")})")
  expect_equal(fmt(Diagram(list(f, g))), "Diagram({CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"))): EmptySet, IdentityMorphism(Object(\"A\")): EmptySet, IdentityMorphism(Object(\"B\")): EmptySet, IdentityMorphism(Object(\"C\")): EmptySet, NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"): EmptySet, NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"): EmptySet}, {}, {Object(\"A\"), Object(\"B\"), Object(\"C\")})")
  expect_equal(fmt(Diagram(list(f, g, h))), "Diagram({CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"))): EmptySet, CompositeMorphism((NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"), NamedMorphism(Object(\"C\"), Object(\"D\"), \"h\"))): EmptySet, CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"), NamedMorphism(Object(\"C\"), Object(\"D\"), \"h\"))): EmptySet, IdentityMorphism(Object(\"A\")): EmptySet, IdentityMorphism(Object(\"B\")): EmptySet, IdentityMorphism(Object(\"C\")): EmptySet, IdentityMorphism(Object(\"D\")): EmptySet, NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"): EmptySet, NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"): EmptySet, NamedMorphism(Object(\"C\"), Object(\"D\"), \"h\"): EmptySet}, {}, {Object(\"A\"), Object(\"B\"), Object(\"C\"), Object(\"D\")})")
  expect_equal(fmt(Diagram(list(list(f, "unique"), list(g, "unique")))), "Diagram({CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"))): {unique}, IdentityMorphism(Object(\"A\")): EmptySet, IdentityMorphism(Object(\"B\")): EmptySet, IdentityMorphism(Object(\"C\")): EmptySet, NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"): {unique}, NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"): {unique}}, {}, {Object(\"A\"), Object(\"B\"), Object(\"C\")})")
  expect_equal(fmt(Diagram(list(list(f, c("unique", "isomorphism")), list(g, "unique")))), "Diagram({CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"))): {unique}, IdentityMorphism(Object(\"A\")): EmptySet, IdentityMorphism(Object(\"B\")): EmptySet, IdentityMorphism(Object(\"C\")): EmptySet, NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"): {isomorphism, unique}, NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"): {unique}}, {}, {Object(\"A\"), Object(\"B\"), Object(\"C\")})")
  expect_equal(fmt(Diagram(list(f, g), list(g * f))), "Diagram({CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"))): EmptySet, IdentityMorphism(Object(\"A\")): EmptySet, IdentityMorphism(Object(\"B\")): EmptySet, IdentityMorphism(Object(\"C\")): EmptySet, NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"): EmptySet, NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"): EmptySet}, {CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"))): EmptySet}, {Object(\"A\"), Object(\"B\"), Object(\"C\")})")
  expect_equal(fmt(Diagram(list(f, g), list(list(g * f, "unique")))), "Diagram({CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"))): EmptySet, IdentityMorphism(Object(\"A\")): EmptySet, IdentityMorphism(Object(\"B\")): EmptySet, IdentityMorphism(Object(\"C\")): EmptySet, NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"): EmptySet, NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"): EmptySet}, {CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"))): {unique}}, {Object(\"A\"), Object(\"B\"), Object(\"C\")})")
  expect_equal(fmt(Diagram(list(f, g), list(h))), "Diagram({CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"))): EmptySet, IdentityMorphism(Object(\"A\")): EmptySet, IdentityMorphism(Object(\"B\")): EmptySet, IdentityMorphism(Object(\"C\")): EmptySet, NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"): EmptySet, NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"): EmptySet}, {}, {Object(\"A\"), Object(\"B\"), Object(\"C\")})")
  expect_equal(fmt(Diagram(list(f, NamedMorphism(B, A, "f1")))), "Diagram({CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"A\"), \"f1\"))): EmptySet, CompositeMorphism((NamedMorphism(Object(\"B\"), Object(\"A\"), \"f1\"), NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"))): EmptySet, IdentityMorphism(Object(\"A\")): EmptySet, IdentityMorphism(Object(\"B\")): EmptySet, NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"): EmptySet, NamedMorphism(Object(\"B\"), Object(\"A\"), \"f1\"): EmptySet}, {}, {Object(\"A\"), Object(\"B\")})")
  expect_equal(fmt(hom(Diagram(list(f, g)), A, C)), "({CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\")))}, EmptySet)")
  expect_equal(fmt(hom(Diagram(list(f, g), list(g * f)), A, C)), "({CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\")))}, {CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\")))})")
  expect_equal(fmt(hom(Diagram(list(f, g)), A, B)), "({NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\")}, EmptySet)")
  expect_equal(fmt(is_subdiagram(Diagram(list(f, g, h)), Diagram(list(f, g)))), "True")
  expect_equal(fmt(is_subdiagram(Diagram(list(f, g)), Diagram(list(f, g, h)))), "False")
  expect_equal(fmt(is_subdiagram(Diagram(list(list(f, "unique"), list(g, list()))), Diagram(list(f)))), "False")
  expect_equal(fmt(subdiagram_from_objects(Diagram(list(f, g, h)), FiniteSet(A, B, C))), "Diagram({CompositeMorphism((NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"), NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"))): EmptySet, IdentityMorphism(Object(\"A\")): EmptySet, IdentityMorphism(Object(\"B\")): EmptySet, IdentityMorphism(Object(\"C\")): EmptySet, NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"): EmptySet, NamedMorphism(Object(\"B\"), Object(\"C\"), \"g\"): EmptySet}, {}, {Object(\"A\"), Object(\"B\"), Object(\"C\")})")
  expect_equal(fmt(subdiagram_from_objects(Diagram(list(list(f, "unique"), list(g, "unique")), list(list(g * f, "unique"))), FiniteSet(A, B))), "Diagram({IdentityMorphism(Object(\"A\")): EmptySet, IdentityMorphism(Object(\"B\")): EmptySet, NamedMorphism(Object(\"A\"), Object(\"B\"), \"f\"): {unique}}, {}, {Object(\"A\"), Object(\"B\")})")
  expect_equal(fmt(diagram_objects(Diagram(list(f, g)))), "{Object(\"A\"), Object(\"B\"), Object(\"C\")}")
  expect_equal(fmt(Category("K", FiniteSet(A, B), list(Diagram(list(f))))), "Category(\"K\")")
  expect_equal(fmt(category_objects(Category("K", FiniteSet(A, B)))), "Class({Object(\"A\"), Object(\"B\")})")
  expect_error(f * g, "Uncomposable")
  expect_error(NamedMorphism(A, B, ""), "Empty morphism")
})
